ns:RegisterSpecGuide("PALADIN", "Holy", {
	role = "healer",
	stats = { "Intellect", "Haste Rating", "Mana per 5 Sec", "Spell Power", "Critical Strike Rating" },
	enchants = {
		{ slot = "Head", options = { { kind = "item", id = 50370, enchant = 3819, name = "Arcanum of Blissful Mending" } },
		  note = "The stat value for Crit and MP5 are extremely close here, to the point where they're both essentially equal with slight edges to both. Crit adds a small amount of variance and throughput, while MP5 is a very steady option that is independent of how much you're casting." },
		{ slot = "Shoulder", options = { { kind = "item", id = 50336, enchant = 3809, name = "Greater Inscription of the Crag" } },
		  note = "As with the Arcanums, the stat values are quite equal here.\n\nIf you have Inscription, you can use {spell:61118} or {spell:61120} instead, which are profession-specific. This is the main reason why it's one of the worst professions for Holy Paladin; spellpower is a very weak stat, and this is the only thing you get out of it in terms of raiding stat bonuses." },
		{ slot = "Back", options = { { kind = "spell", id = 47898, enchant = 3831, skill = "Tailoring" } },
		  note = "{spell:55769} is a surprisingly viable sustain option that provides around to 40 to 42 mp5, but is a profession-only benefit.\n\nIf you don't have Tailoring, you will go with {spell:47898}." },
		{ slot = "Chest", options = { { kind = "spell", id = 60692, enchant = 3832 }, { kind = "spell", id = 27958, enchant = 3233 } },
		  note = "Both options are viable here and come down to preference. The stats enchant gives some HP, crit, and SP (through int), while the mana enchant gives a little less than 100 more mana (after accounting for buffs). However, in general we would recommend the stats enchant, particularly during progression, as having the extra HP buffer can be particularly worthwhile with a lot of unavoidable raid damage in WOTLK." },
		{ slot = "Waist", options = { { kind = "item", id = 41611, name = "Eternal Belt Buckle", skill = "Engineering" } },
		  note = "Eternal Belt Buckle is a BoE Blacksmithing item that lets you add an extra prismatic gem socket to your gear.\n\nIf you have Engineering, you can additionally enchant {spell:54736}, which stacks with the socket \"enchant.\" However, its only real use is on Ulduar trash. If you're in a high tier guild that can benefit from the marginal gain of this, it's decently good for the few uses in the raid, but it is totally useless in any other raid tier." },
		{ slot = "Wrist", options = { { kind = "spell", id = 44555, enchant = 1119, skill = "Blacksmithing" } },
		  note = "is your go-to option for this slot.\n\nIf you have Leatherworking, a high-throughput option is {spell:57691}, another profession-only enchant replacement for this slot. However, be aware that it's a lesser sustain option and even if you have LW, in general the Int enchant will be more useful.\n\n{spell:55628} is one of the two Blacksmithing-only perks." },
		{ slot = "Hands", options = { { kind = "spell", id = 54999, enchant = 3604, skill = "Engineering" }, { kind = "spell", id = 44592, enchant = 3246, skill = "Blacksmithing" } },
		  note = "You will want to have {spell:54999} as it is a small throughput cooldown that competes with an otherwise very sub-par enchant. You will never haste cap {spell:48782}, so additional haste is always very powerful. If you don't have Engineering, you'll have to settle for the SP enchant.\n\n{spell:55641} is the other one of the two Blacksmithing-only perks." },
		{ slot = "Legs", options = { { kind = "item", id = 41604, enchant = 3721, name = "Sapphire Spellthread" } },
		  note = "The other enchant option gives Spirit instead of Stamina, and Spirit does nothing for Holy Paladins in WotLK." },
		{ slot = "Feet", options = { { kind = "item", id = 41118, enchant = 3606, name = "Nitro Boosts", skill = "Engineering" } },
		  note = "One of Paladin's biggest weaknesses in WotLK is a lack of on-demand mobility, which Nitro Boosts helps significantly. On certain fights with lots of continuous movement, however, you may prefer to have the consistent movespeed increase of {spell:47901}.\n\nPrimarily you'll want to use Nitro Boosts, but always keep an eye out for a second pair of uncontested boots that you can put Tuskarr's Vitality on for fights like Yogg-Saron, which have lots of continuous small movement." },
		{ slot = "Weapon", options = { { kind = "spell", id = 27968, enchant = 2666 } },
		  note = "Since spellpower is just a fairly weak stat, the TBC Int enchant is just the winner here in all cases. Despite the stat values being very similar, Int pulls ahead on any fight with downtime between casts and in general, sustain is what you're concerned with as a Holy Paladin." },
		{ slot = "OffHand", options = { { kind = "spell", id = 60653, enchant = 1128 } },
		  note = "Generally, shields will be much higher value (as well as significantly less contested) than offhands, largely due to this enchant." },
		{ slot = "Ring", options = { { kind = "spell", id = 44636, enchant = 3840, skill = "Enchanting" } },
		  note = "As in TBC, this requires Enchanting and is a self-only enchant. As with Inscription, this is a discouraged profession option." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41401, name = "Insightful Earthsiege Diamond" } },
		  note = "Insightful Earthsiege Diamond is the best sustain option by far and is very easy to hit. There just isn't a better choice in WotLK. It'll have a rough value of 60-80 MP5, so you really want to make sure you have a meta gem socket available ASAP.\nFor the meta gem requirement, it's still highly advised to use 1 orange and 1 green gem, as even with the new Nightmare Tear it's more stat value for the 2 gems rather than the prismatic. However, it is marginal enough that it is preference, and if you prefer to have slightly more haste or int from gems, you can choose to use the Tear instead." },
		{ slot = "Yellow", options = { { kind = "item", id = 40123, name = "Brilliant King's Amber" }, { kind = "item", id = 40012, name = "Brilliant Autumn's Glow" }, { kind = "item", id = 40017, name = "Quick Autumn's Glow", skill = "Jewelcrafting" } },
		  note = "With the advent of Phase 3 and the Trial of the Crusader, epic gems are now available. They are strict upgrades from the rare gems with no socketed limitations, unlike Stormjewels. Because they're just strict upgrades, every other aspect of gemming is the same. While Brilliant Stormjewel is still an option, it's the same as the unlimited epic gems and likely slightly more expensive, so it's not recommended to use them anymore.\n\nThese will be the vast majority of your gems, and you should ignore socket bonuses to gem yellows. The vast majority of Holy Paladins will be best served by using Intellect gems; however, if you're in a high-tier guild or speedrunning you may consider Haste gems as th" },
	},
	priority = {
		{ 53563, "- Always keep this up on the person who will take the most consistent damage. You may need to swap these on tank-swap fights accordingly." },
		{ 54155, "- Always keep this up." },
		{ 53601, "- Always keep this up on your assigned target." },
		{ 54428, "- Check your {spell:54428} cooldown and the remaining fight length (generally approximated by boss hp) to see if you will be needing to use {spell:54428} to fin" },
		{ 48782, "spam - When all maintenance buffs are up and mana is accounted for, maximize {spell:48782} spam on appropriate targets." },
	},
	opener = "",
})

ns:RegisterSpecGuide("PALADIN", "Protection", {
	role = "tank",
	stats = {  },
	enchants = {
		{ slot = "Head", options = { { kind = "item", id = 50369, enchant = 3818, name = "Arcanum of the Stalwart Protector" } },
		  note = "While we generally favor stam over defense in almost every case, Arcanum of the Stalwart Protector offers more defense than average per stamina.\n\nArcanum of Toxic Warding, Arcanum of the Frosty Soul, Arcanum of the Flame's Soul, Arcanum of the Fleeing Shadow can all be used to augment your survivability on encounters with high, resistable magic damage." },
		{ slot = "Shoulder", options = { { kind = "item", id = 44957, enchant = 3852, name = "Greater Inscription of the Gladiator" }, { kind = "spell", id = 61119, enchant = 3837 }, { kind = "item", id = 50337, enchant = 3811, name = "Greater Inscription of the Pinnacle" } },
		  note = "None of the other options offer any stamina, this also helps you shore up crit cap deficiencies." },
		{ slot = "Back", options = { { kind = "spell", id = 44591, enchant = 1951 } },
		  note = "These are all pretty similar, you're always going to end up wanting to use {spell:44591} if you're still looking to get crit immune, otherwise {spell:47672} vs Flexweave Underlay is bound to use-case." },
		{ slot = "Chest", options = { { kind = "spell", id = 47900, enchant = 3297 } },
		  note = "As with the other defense enchants {spell:47766} is important to pick up if you're not yet crit immune. {spell:47900} and {spell:60692} are virtually the same in budget making it more of a preferential choice than anything else." },
		{ slot = "Wrist", options = { { kind = "spell", id = 57690, enchant = 3757 }, { kind = "spell", id = 62256, enchant = 3850 } },
		  note = "{spell:57690} is a great exclusive option for Leatherworkers. Otherwise is no legitimate alternative here, pick up {spell:62256}.\n\nLeatherworkers also get access to {spell:57699} and similar resistance enchants for their wrist slots, these are generally not extraordinary to us as tanks though when they are good, they are usually very strong. Two very noteworthy encounters would be Heroic 25 man Anub'arak and 25 man hardmode Iron Council. Both of these fights lend themselves exceptionally well to tanks wearing some nature resistance." },
		{ slot = "Hands", options = { { kind = "spell", id = 63770, enchant = 3860 } },
		  note = "{spell:63770} is a major tanking enhancement in an otherwise uninteresting slot, making this a strong pick up for all tanks. {spell:54999} is the highest DPS glove enhancement available to engineers and {spell:54998} has a utility function in the additional ranged ability, as well as some DPS expression. All of these are only available to engineers. {spell:44625} is a direct upgrade from TBC and is the best threat enchant for the glove slot." },
		{ slot = "Legs", options = { { kind = "item", id = 38373, enchant = 3822, name = "Frosthide Leg Armor" }, { kind = "item", id = 38371, enchant = 3325, name = "Jormungar Leg Armor" } },
		  note = "{spell:60583} is a leatherworking exclusive leg enchant, it's the same as everyone else's but significantly cheaper. Non leatherworkers will go for, Frosthide Leg Armor as is the choice with the highest stamina and will usually be out go-to leg enchant. Jormungar Leg Armor is a slightly worse but potentially less expensive alternative." },
		{ slot = "Feet", options = { { kind = "spell", id = 44528, enchant = 1075 }, { kind = "item", id = 38376, enchant = 3330, name = "Heavy Borean Armor Kit" }, { kind = "spell", id = 47901, enchant = 3232 }, { kind = "spell", id = 44589, enchant = 983 } },
		  note = "If you're an engineer then we really want to stress that {spell:55016} is a superb feet enchant that you should heavily consider even if you only have one pair of boots. Pick up {spell:47901} if you don't run {spell:26023}." },
		{ slot = "Weapon", options = { { kind = "spell", id = 64579, enchant = 3870 } },
		  note = "{spell:64579} stands unique in WotLK in its effect. While completely void of any offensive potential, you should not dismiss this enchant. Consider it something akin to a +200 stamina proc when you most need it, unlike other defensive enchants this is a highly reliable enchant. While it will certainly not save your life single-handedly against most encounters, it does reduce the amount of healing you need to recieve to live significantly.\n\nOtherwise the standard enchant {spell:59619} sits as a strong pick up that will fit into every set imaginable." },
		{ slot = "OffHand", options = { { kind = "item", id = 44936, enchant = 3849, name = "Titanium Plating" }, { kind = "spell", id = 44489, enchant = 1952 } },
		  note = "Titanium Plating is the superior physical mitigation enhancement here, however in the event that you are more concerned with magical damage {spell:34009} is quite strong." },
		{ slot = "Ring", options = { { kind = "spell", id = 59636, enchant = 3791 }, { kind = "spell", id = 44645, enchant = 3839 } },
		  note = "If you're an enchanter you have the unique ability to enchant your own rings. We'll advice opting for stamina here, always." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41380, name = "Austere Earthsiege Diamond" } },
		  note = "Austere Earthsiege Diamond is the best meta gem available for Protection Paladins. The armor modifier makes this our best defensive meta gem for almost all circumstances. Effulgent Skyflare Diamond is purely a foil for our armor meta, it does the same thing though only to magic damage and is therefor less applicable to most tanking." },
		{ slot = "Blue", options = { { kind = "item", id = 40119, name = "Solid Majestic Zircon" }, { kind = "item", id = 40008, name = "Solid Sky Sapphire" } },
		  note = "Stamina are our mainstay gems, can significantly augment your survivability. Stamina is always relevant to us as tanks, is the most universal stat that we can acquire as it is effective against all forms of damage. as a rule we try to socket these most of the time." },
		{ slot = "Yellow", options = { { kind = "item", id = 40167, name = "Enduring Eye of Zul" }, { kind = "item", id = 40089, name = "Enduring Forest Emerald" }, { kind = "item", id = 40088, name = "Vivid Forest Emerald" } },
		  note = "We opt into green gems for yellow sockets, because stamina is awarded at greater rates than other stats. This allows us to double dip, giving us more stats per gem in tandem with matching desireable socket bonuses.\n\nMatching and using yellow gem slots is much more important than any other socket bonus, as if you are unable to reach crit immunity or hit cap through your gear, it is heavily advised that you make up for any of these deficiencies through your gems. Hit capping is not always necessary though the benefits of reaching your 8% cap is very much recommended." },
		{ slot = "Red", options = { { kind = "item", id = 40130, name = "Shifting Dreadstone" }, { kind = "item", id = 40023, name = "Shifting Twilight Opal" }, { kind = "item", id = 40022, name = "Sovereign Twilight Opal" }, { kind = "item", id = 40034, name = "Guardian's Twilight Opal" } },
		  note = "Matching red sockets is much less important than stacking either stamina or reaching hit cap/crit immunity. We can of course match red sockets, preferably at +6 stamina, though it is almost always a luxury decision. We use purple gems for the same reason we use green gems, these award more relevant stats to us than mono colored reds.\n\nThe real exception to above is if you are below expertise soft cap, utilizing expertise gems will net you significant value as it will suppress both dodge and parry below 26 expertise skill. If you are sitting just below expertise hard cap, we think you should likewise consider expertise gems to push you into capping." },
	},
	priority = {
	},
	opener = "",
})

ns:RegisterSpecGuide("PALADIN", "Retribution", {
	role = "melee",
	stats = { "Hit Rating", "Expertise", "Strength", "Critical Strike Rating ~= Agi", "Haste Rating", "Attack Power", "Armor Penetration" },
	enchants = {
		{ slot = "Shoulder", options = { { kind = "spell", id = 61117, enchant = 3835 }, { kind = "item", id = 44871, enchant = 3808, name = "Greater Inscription of the Axe" }, { kind = "item", id = 28888, enchant = 2986, name = "Greater Inscription of Vengeance" } },
		  note = "{spell:61117} is available for inscription only, which is not a recommended path for Retribution Paladin. as such, in most cases Greater Inscription of the Axe is probably your better enchant to get from The Sons of Hodir exalted. Until that point, Greater Inscription of Vengeance from TBC is your go to, an equivalent is available in wrath under Lesser Inscription of the Axe." },
		{ slot = "Back", options = { { kind = "item", id = 41111, enchant = 3605, name = "Flexweave Underlay" }, { kind = "spell", id = 60663, enchant = 1099 } },
		  note = "Flexweave Underlay is available only through Engineering. This is your best profession to use, but if you don't have it, {spell:60663} is available providing 1 less agility." },
		{ slot = "Chest", options = { { kind = "spell", id = 60692, enchant = 3832 } },
		  note = "{spell:60692} is what you want for raiding." },
		{ slot = "Wrist", options = { { kind = "item", id = 43097, enchant = 3756, name = "Fur Lining - Attack Power" }, { kind = "spell", id = 44575, enchant = 3845 }, { kind = "spell", id = 44598, enchant = 3231 } },
		  note = "Fur Lining - Attack Power is the only available through Leatherworking, which is not one of your best professions. When you don't have this, {spell:44575} > {spell:44598}. 50 AP provides ~ 30 dps while 15 expertise will provide between 8 and 20 dps depending on if it provides 1 or 2 bonus value (.25% or .50% dodge reduction). Even if you're below expertise cap, the attackpower is better." },
		{ slot = "Hands", options = { { kind = "spell", id = 54999, enchant = 3604 }, { kind = "spell", id = 60668, enchant = 1603 }, { kind = "spell", id = 44484, enchant = 3231 } },
		  note = "{spell:54999} is an engineering specific enchant and is your best enchant by about 40 dps over other enchants. You want to use this combined with your {spell:31884} for optimal damage, and then on cooldown on the use when {spell:31884} is not active. If you're not engineering (even though you should be), {spell:60668} > {spell:44484} in all situations, even if you're under expertise cap." },
		{ slot = "Legs", options = { { kind = "item", id = 38374, enchant = 3823, name = "Icescale Leg Armor" }, { kind = "item", id = 38372, enchant = 3326, name = "Nerubian Leg Armor" } },
		  note = "Icescale Leg Armor is pretty cut and dry the best enchant." },
		{ slot = "Feet", options = { { kind = "item", id = 41118, enchant = 3606, name = "Nitro Boosts" } },
		  note = "While Nitro Boosts are ~ 4-6 lower dps than the other two options, its still highly recommended to use Nitro Boosts over the other two as the added utility is a boon to the paladin, especially since you do not have any active mobility buttons otherwise. In the case you aren't engineering, {spell:60623} are approximately equal to {spell:60763} if you need the hit rating, while {spell:60763} pull ahead if you do not need the hit. {spell:47901} are not needed ever with 2 ranks of {spell:26023}" },
		{ slot = "Weapon", options = { { kind = "spell", id = 59621, enchant = 3789 }, { kind = "spell", id = 60691, enchant = 3827 } },
		  note = "{spell:59621} is ahead of {spell:60691} by about 50 dps average, and gives you a damage proc to play with to get a bit more value out of other active cooldowns if you line them up correctly." },
		{ slot = "Ring", options = { { kind = "spell", id = 44645, enchant = 3839 } },
		  note = "If you are an enchanter for some reason, {spell:44645} is the the best enchant for you to put on your own rings. This cannot be done by anyone other than enchanters." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41398, name = "Relentless Earthsiege Diamond" }, { kind = "spell", id = 55389 } },
		  note = "Relentless Earthsiege Diamond is the better meta gem of the two options, for two reasons. 1) our scaling with Agi is slightly better than with crit due to {spell:56525} and 2) because only needing 1 blue socket is overall better. This gem also only has one yellow requirement, which can be fulfilled very easily, making your gemming extremely strait forward when you have your hit cap handled." },
		{ slot = "Red", options = { { kind = "item", id = 42142, name = "Bold Dragon's Eye" }, { kind = "item", id = 40003, name = "Precise Scarlet Ruby" } },
		  note = "For red gems you are either going for Precise Scarlet Ruby or Bold Scarlet Ruby based on if you are expertise capped or not. Precise Scarlet Ruby is a new gem for Wrath of the Lich King, and gives \"about\" two expertise value per gem (0.5% dodge reduction), so this is a useful thing to note while you're getting your lower level gear set up. You do want to shoot for expertise cap, but overshooting with one of these is an overall loss. Bold Scarlet Ruby is your go to otherwise. When at all possible, you want to be able to run 3 Bold Dragon's Eye in your gear across your slots." },
		{ slot = "Yellow", options = { { kind = "item", id = 40014, name = "Rigid Autumn's Glow" } },
		  note = "For yellow gems, you want to get your physical hit cap. Any higher does have an effect due to both {spell:48801} and {spell:48819} working on spell hit, as well as {spell:53382} having partial resists enabled, however its overall a damage loss to do so over using those yellows for improving your strength is a much better avenue." },
		{ slot = "Blue", options = { { kind = "item", id = 49110, name = "Nightmare Tear" }, { kind = "item", id = 42702, name = "Enchanted Tear" } },
		  note = "In an ideal world you will need only 1 blue gem for your meta gem, which means you want to use Nightmare Tear, providing 10 Strength and Agility, which is a fantastic deal when compared to Sovereign Twilight Opal. Enchanted Tear is also an option as it adds 2 less strength in favor of 6 agility, which ends up being approximately equal at the end of the day. The extra intel on both of these will also increase your mana pool for {spell:53408}." },
	},
	priority = {
		{ 35395, "" },
		{ 53408, "" },
		{ 53385, "" },
